function sortArray(nums) {
  const rest = nums.slice();
  const out = [];
  while (rest.length > 0) {
    let smallest = 0;
    for (let i = 1; i < rest.length; i++) {
      if (rest[i] < rest[smallest]) smallest = i;
    }
    out.push(rest[smallest]);
    rest.splice(smallest, 1);
  }
  return out;
}

