function sortAndCount(values) {
  if (values.length <= 1) return { sorted: values.slice(), count: 0 };
  const middle = Math.floor(values.length / 2);
  const left = sortAndCount(values.slice(0, middle));
  const right = sortAndCount(values.slice(middle));
  const merged = [];
  let i = 0;
  let j = 0;
  let crossing = 0;
  while (i < left.sorted.length && j < right.sorted.length) {
    if (left.sorted[i] <= right.sorted[j]) {
      merged.push(left.sorted[i]);
      i += 1;
    } else {
      merged.push(right.sorted[j]);
      j += 1;
      crossing += left.sorted.length - i;
    }
  }
  while (i < left.sorted.length) { merged.push(left.sorted[i]); i += 1; }
  while (j < right.sorted.length) { merged.push(right.sorted[j]); j += 1; }
  return { sorted: merged, count: left.count + right.count + crossing };
}

function countInversions(nums) {
  return sortAndCount(nums).count;
}

